window.WEDDING_TEMPLATE = { html: "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"description\" content=\"Undangan pernikahan Surya Septa Pratama &amp; Fransiska Wijaya — Minggu, 6 Februari 2028, kediaman mempelai wanita.\">\n  <title>Undangan Pernikahan — Surya &amp; Fransiska</title>\n  <style>\n/* ============================================================\n   Undangan Pernikahan — Surya & Fransiska\n   Palet: maroon tua, sogan, krem/gading, aksen emas\n   ============================================================ */\n\n:root {\n  --maroon: #4a1520;\n  --maroon-deep: #380f18;\n  --sogan: #6b4423;\n  --cream: #fdf6e3;\n  --ivory: #f7ecd7;\n  --gold: #b49158;\n  --gold-dark: #8c6b35;\n  --ink: #3d2b1a;\n  --ink-soft: #5a4632;\n  --card: #fffdf6;\n  --shadow: 0 10px 30px rgba(74, 21, 32, 0.12);\n\n  --font-display: \"Palatino Linotype\", Palatino, \"Book Antiqua\", Georgia, \"Times New Roman\", serif;\n  --font-body: \"Segoe UI\", \"Helvetica Neue\", \"Trebuchet MS\", Arial, sans-serif;\n\n  --speed: 320ms;\n}\n\n* { box-sizing: border-box; margin: 0; padding: 0; }\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n  font-family: var(--font-body);\n  font-size: 1rem;\n  line-height: 1.65;\n  color: var(--ink);\n  background-color: var(--cream);\n  position: relative;\n}\n\n/* Latar batik full-bleed halus di belakang kolom undangan */\nbody::before {\n  content: \"\";\n  position: fixed;\n  inset: 0;\n  z-index: -2;\n  background: url(\"data:image/svg+xml;base64,\") repeat;\n  background-size: 120px 120px;\n  opacity: 0.08;\n  pointer-events: none;\n}\n\n/* Kolom undangan, mobile-first, dibatasi di desktop */\n.column {\n  max-width: 520px;\n  margin: 0 auto;\n  padding: 2.25rem 1.25rem;\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px; height: 1px;\n  padding: 0; margin: -1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* ---------- Fokus & tipografi dasar ---------- */\n:focus-visible {\n  outline: 3px solid var(--gold-dark);\n  outline-offset: 2px;\n  border-radius: 2px;\n}\n\nh1, h2, h3, h4, blockquote cite {\n  font-family: var(--font-display);\n  color: var(--maroon);\n  line-height: 1.25;\n}\n\n.section__title {\n  font-size: 1.7rem;\n  letter-spacing: 0.03em;\n  margin-bottom: 1rem;\n  text-align: center;\n}\n\n.lead {\n  margin-bottom: 1.25rem;\n  color: var(--ink-soft);\n  text-align: center;\n}\n\n/* ---------- Tombol ---------- */\n.btn {\n  display: inline-block;\n  font-family: var(--font-body);\n  font-size: 0.95rem;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  padding: 0.7rem 1.6rem;\n  border: 1px solid transparent;\n  border-radius: 999px;\n  cursor: pointer;\n  text-decoration: none;\n  transition: transform var(--speed) ease, box-shadow var(--speed) ease, background-color var(--speed) ease, color var(--speed) ease;\n}\n\n.btn:hover { transform: translateY(-2px); box-shadow: var(--shadow); }\n.btn:active { transform: translateY(0); }\n\n.btn--gold {\n  background-color: var(--gold);\n  color: var(--maroon-deep);\n  border-color: var(--gold-dark);\n}\n\n.btn--outline {\n  background-color: transparent;\n  color: var(--sogan);\n  border-color: var(--gold-dark);\n}\n\n.btn--outline:hover { background-color: rgba(180, 145, 88, 0.15); }\n\n/* ============================================================\n   1. Cover / layar pembuka\n   ============================================================ */\n.cover {\n  position: fixed;\n  inset: 0;\n  z-index: 50;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  padding: 1.5rem;\n  background-color: var(--maroon);\n  color: var(--cream);\n  transition: opacity 480ms ease, visibility 480ms ease;\n}\n\n.cover.is-open {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n\n.cover__batik {\n  position: absolute;\n  inset: 0;\n  background: url(\"data:image/svg+xml;base64,\") repeat;\n  background-size: 100px 100px;\n  opacity: 0.14;\n  pointer-events: none;\n}\n\n.cover__inner {\n  position: relative;\n  max-width: 520px;\n  border: 1px solid rgba(180, 145, 88, 0.55);\n  outline: 1px solid rgba(180, 145, 88, 0.25);\n  outline-offset: 6px;\n  padding: 3rem 1.5rem;\n}\n\n.cover__eyebrow {\n  font-family: var(--font-display);\n  letter-spacing: 0.35em;\n  text-transform: uppercase;\n  font-size: 0.8rem;\n  color: var(--gold);\n  margin-bottom: 1.25rem;\n}\n\n.cover__names {\n  font-size: clamp(2.3rem, 9vw, 3.4rem);\n  color: var(--cream);\n  margin-bottom: 0.75rem;\n}\n\n.cover__names .amp {\n  color: var(--gold);\n  font-size: 0.6em;\n  padding: 0 0.2em;\n}\n\n.cover__date {\n  font-size: 1.05rem;\n  letter-spacing: 0.08em;\n  color: var(--ivory);\n  margin-bottom: 1.5rem;\n}\n\n.cover__hint {\n  font-size: 0.9rem;\n  color: rgba(253, 246, 227, 0.85);\n  margin-bottom: 2rem;\n}\n\n/* Gembok gulir saat cover terbuka */\nbody.cover-open { overflow: hidden; }\n\n/* ---------- Header kecil ---------- */\n.site-header {\n  text-align: center;\n  padding: 0.9rem 1rem 0;\n}\n\n.site-header__brand {\n  font-family: var(--font-display);\n  font-size: 1.15rem;\n  color: var(--gold-dark);\n  letter-spacing: 0.12em;\n}\n\n/* ============================================================\n   2. Hero\n   ============================================================ */\n.hero { text-align: center; }\n\n.hero__photo {\n  position: relative;\n  margin: 1.5rem auto 1.75rem;\n  width: min(260px, 72vw);\n  aspect-ratio: 3 / 4;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background:\n    linear-gradient(160deg, rgba(180, 145, 88, 0.35), rgba(74, 21, 32, 0.55)),\n    url(\"data:image/svg+xml;base64,\") repeat,\n    var(--ivory);\n  background-size: cover, 200px 200px, auto;\n  border: 1px solid var(--gold);\n  outline: 1px solid rgba(180, 145, 88, 0.4);\n  outline-offset: 6px;\n  box-shadow: var(--shadow);\n}\n\n.hero__monogram {\n  font-family: var(--font-display);\n  font-size: clamp(2.4rem, 10vw, 3.2rem);\n  color: var(--cream);\n  text-shadow: 0 2px 10px rgba(56, 15, 24, 0.55);\n  letter-spacing: 0.08em;\n}\n\n.hero__heart {\n  color: var(--gold);\n  font-size: 0.55em;\n  padding: 0 0.25em;\n  vertical-align: 0.12em;\n}\n\n.hero__names {\n  font-size: 1.65rem;\n  margin-bottom: 0.4rem;\n}\n\n.hero__date {\n  color: var(--ink-soft);\n  letter-spacing: 0.06em;\n  margin-bottom: 0.75rem;\n}\n\n.divider {\n  height: 42px;\n  max-width: 360px;\n  margin: 0 auto 1rem;\n  background: url(\"data:image/svg+xml;base64,\") no-repeat center / contain;\n}\n\n.scroll-cue {\n  display: inline-block;\n  font-size: 0.85rem;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--gold-dark);\n  text-decoration: none;\n  animation: bob 2.4s ease-in-out infinite;\n}\n\n@keyframes bob {\n  0%, 100% { transform: translateY(0); }\n  50% { transform: translateY(5px); }\n}\n\n/* ---------- Seksi umum ---------- */\n.section { padding: 1.5rem 0; }\n\n.section--tinted {\n  background-color: var(--ivory);\n  border-top: 1px solid rgba(180, 145, 88, 0.3);\n  border-bottom: 1px solid rgba(180, 145, 88, 0.3);\n}\n\n/* ============================================================\n   3. Countdown\n   ============================================================ */\n.countdown {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 0.6rem;\n}\n\n.countdown__box {\n  background: var(--card);\n  border: 1px solid var(--gold);\n  border-radius: 10px;\n  padding: 0.85rem 0.3rem 0.7rem;\n  text-align: center;\n  box-shadow: var(--shadow);\n}\n\n.countdown__num {\n  display: block;\n  font-family: var(--font-display);\n  font-variant-numeric: tabular-nums;\n  font-feature-settings: \"tnum\" 1;\n  font-size: 1.7rem;\n  line-height: 1.1;\n  color: var(--maroon);\n  min-width: 2ch;\n}\n\n.countdown__label {\n  display: block;\n  margin-top: 0.25rem;\n  font-size: 0.72rem;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n  color: var(--gold-dark);\n}\n\n/* ============================================================\n   4. Mempelai\n   ============================================================ */\n.quote {\n  margin: 0 0 1.75rem;\n  padding: 1.1rem 1.25rem;\n  border-left: 3px solid var(--gold);\n  background: var(--card);\n  border-radius: 0 10px 10px 0;\n  font-style: italic;\n  color: var(--ink-soft);\n}\n\n.quote cite {\n  display: block;\n  margin-top: 0.6rem;\n  font-size: 0.9rem;\n  font-style: normal;\n  color: var(--gold-dark);\n  text-align: right;\n}\n\n.couple-card {\n  position: relative;\n  background: var(--card);\n  border: 1px solid rgba(180, 145, 88, 0.45);\n  border-radius: 12px;\n  padding: 1.5rem 1.25rem;\n  margin-bottom: 1.25rem;\n  text-align: center;\n  box-shadow: var(--shadow);\n}\n\n.couple-card::before {\n  content: \"\";\n  position: absolute;\n  inset: 6px;\n  border: 1px solid rgba(180, 145, 88, 0.35);\n  border-radius: 8px;\n  background: url(\"data:image/svg+xml;base64,\") repeat;\n  background-size: 80px 80px;\n  opacity: 0.07;\n  pointer-events: none;\n}\n\n.couple-card > * { position: relative; }\n\n.couple-card__badge {\n  width: 52px; height: 52px;\n  margin: 0 auto 0.9rem;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--font-display);\n  font-size: 1.5rem;\n  color: var(--cream);\n  background: radial-gradient(circle at 30% 30%, var(--sogan), var(--maroon));\n  border: 2px solid var(--gold);\n}\n\n.couple-card__name { font-size: 1.45rem; margin-bottom: 0.15rem; }\n\n.couple-card__role {\n  font-size: 0.78rem;\n  letter-spacing: 0.16em;\n  text-transform: uppercase;\n  color: var(--gold-dark);\n  margin-bottom: 0.6rem;\n}\n\n.couple-card__parents { color: var(--ink-soft); font-size: 0.95rem; }\n\n/* ============================================================\n   5. Acara\n   ============================================================ */\n.event-card {\n  background: var(--card);\n  border: 1px solid rgba(180, 145, 88, 0.45);\n  border-radius: 12px;\n  padding: 1.5rem 1.25rem;\n  margin-bottom: 1.25rem;\n  text-align: center;\n  box-shadow: var(--shadow);\n}\n\n.event-card__title {\n  font-size: 1.35rem;\n  margin-bottom: 0.75rem;\n  padding-bottom: 0.6rem;\n  border-bottom: 1px solid rgba(180, 145, 88, 0.35);\n}\n\n.event-card__row {\n  display: block;\n  margin-bottom: 0.45rem;\n  color: var(--ink-soft);\n  font-size: 0.95rem;\n  text-align: left;\n}\n\n.event-card__icon { margin-right: 0.4rem; }\n\n.event-card .btn { margin-top: 0.9rem; }\n\n/* ============================================================\n   6. Galeri\n   ============================================================ */\n.gallery {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 0.7rem;\n}\n\n.gallery__tile {\n  display: block;\n  width: 100%;\n  height: auto;\n  aspect-ratio: 1 / 1;\n  object-fit: cover;\n  border-radius: 10px;\n  border: 1px solid var(--gold);\n  box-shadow: var(--shadow);\n}\n\n/* ============================================================\n   7. Ucapan &amp; RSVP\n   ============================================================ */\n.rsvp-form {\n  background: var(--card);\n  border: 1px solid rgba(180, 145, 88, 0.45);\n  border-radius: 12px;\n  padding: 1.25rem;\n  box-shadow: var(--shadow);\n}\n\n.field { margin-bottom: 1rem; }\n\n.field label,\n.field legend {\n  display: block;\n  font-weight: 600;\n  font-size: 0.9rem;\n  margin-bottom: 0.35rem;\n  color: var(--sogan);\n}\n\n.field input[type=\"text\"],\n.field textarea {\n  width: 100%;\n  font: inherit;\n  color: var(--ink);\n  background: var(--cream);\n  border: 1px solid rgba(107, 68, 35, 0.35);\n  border-radius: 8px;\n  padding: 0.65rem 0.8rem;\n  resize: vertical;\n}\n\n.field input[type=\"text\"]:focus,\n.field textarea:focus {\n  border-color: var(--gold-dark);\n  outline-offset: 1px;\n}\n\n.field--radio {\n  border: 0;\n}\n\n.radio {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  font-weight: 400 !important;\n  margin-bottom: 0.4rem;\n  cursor: pointer;\n}\n\n.radio input { accent-color: var(--maroon); width: 1.05rem; height: 1.05rem; }\n\n.field__error {\n  margin-top: 0.35rem;\n  font-size: 0.85rem;\n  color: #9c2b1f;\n  font-weight: 600;\n}\n\n.rsvp-form .btn { width: 100%; }\n\n.rsvp-list {\n  list-style: none;\n  margin-top: 1.25rem;\n}\n\n.rsvp-item {\n  background: var(--card);\n  border: 1px solid rgba(180, 145, 88, 0.35);\n  border-radius: 10px;\n  padding: 0.85rem 1rem;\n  margin-bottom: 0.7rem;\n}\n\n.rsvp-item__head {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 0.75rem;\n  margin-bottom: 0.25rem;\n}\n\n.rsvp-item__name {\n  font-family: var(--font-display);\n  font-weight: 700;\n  color: var(--maroon);\n}\n\n.rsvp-item__badge {\n  flex-shrink: 0;\n  font-size: 0.72rem;\n  letter-spacing: 0.06em;\n  padding: 0.15rem 0.6rem;\n  border-radius: 999px;\n  border: 1px solid var(--gold-dark);\n  color: var(--gold-dark);\n  background: rgba(180, 145, 88, 0.12);\n}\n\n.badge--hadir { color: #2c5c3a; border-color: #2c5c3a; background: rgba(44, 92, 58, 0.1); }\n.badge--tidak-hadir { color: #8f2a1e; border-color: #8f2a1e; background: rgba(143, 42, 30, 0.1); }\n.badge--masih-ragu { color: #7a5a12; border-color: #7a5a12; background: rgba(122, 90, 18, 0.1); }\n\n.rsvp-item__msg { color: var(--ink-soft); font-size: 0.95rem; }\n\n.rsvp-item__time {\n  display: block;\n  margin-top: 0.35rem;\n  font-size: 0.75rem;\n  color: var(--gold-dark);\n}\n\n/* ============================================================\n   8. Amplop digital\n   ============================================================ */\n.bank-card {\n  background: var(--card);\n  border: 1px solid var(--gold);\n  border-radius: 12px;\n  padding: 1.5rem 1.25rem;\n  text-align: center;\n  box-shadow: var(--shadow);\n}\n\n.bank-card__bank {\n  font-family: var(--font-display);\n  font-size: 1.2rem;\n  color: var(--maroon);\n  margin-bottom: 0.35rem;\n}\n\n.bank-card__number {\n  font-family: var(--font-display);\n  font-variant-numeric: tabular-nums;\n  font-size: 1.9rem;\n  letter-spacing: 0.08em;\n  color: var(--ink);\n  margin-bottom: 0.25rem;\n}\n\n.bank-card__name {\n  color: var(--ink-soft);\n  font-size: 0.95rem;\n  margin-bottom: 1.1rem;\n}\n\n/* ============================================================\n   9. Penutup &amp; footer\n   ============================================================ */\n.closing {\n  background:\n    linear-gradient(rgba(56, 15, 24, 0.88), rgba(56, 15, 24, 0.88)),\n    url(\"data:image/svg+xml;base64,\") repeat;\n  background-size: auto, 120px 120px;\n  color: var(--cream);\n  text-align: center;\n  padding: 0.75rem 0 1.5rem;\n}\n\n.closing .section__title { color: var(--gold); }\n\n.closing .lead { color: rgba(253, 246, 227, 0.92); }\n\n.closing__names {\n  font-family: var(--font-display);\n  font-size: 1.15rem;\n  margin-top: 1rem;\n}\n\n.closing__names strong {\n  display: inline-block;\n  font-size: 1.5rem;\n  color: var(--gold);\n  margin-top: 0.35rem;\n}\n\n.closing__hashtag {\n  margin-top: 1.25rem;\n  font-family: var(--font-display);\n  font-size: 1.1rem;\n  letter-spacing: 0.1em;\n  color: var(--ivory);\n}\n\n.site-footer {\n  background: var(--maroon-deep);\n  color: rgba(253, 246, 227, 0.75);\n  text-align: center;\n  font-size: 0.8rem;\n  padding: 1rem 1.25rem;\n}\n\n/* ---------- Tombol musik mengambang ---------- */\n.music-toggle {\n  position: fixed;\n  right: 1rem;\n  bottom: 1rem;\n  z-index: 60;\n  width: 44px;\n  height: 44px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.1rem;\n  line-height: 1;\n  color: var(--cream);\n  background: var(--maroon);\n  border: 1px solid var(--gold);\n  border-radius: 50%;\n  box-shadow: var(--shadow);\n  cursor: pointer;\n  transition: background-color var(--speed) ease;\n}\n\n.music-toggle:hover { background-color: var(--sogan); }\n\n.music-toggle[hidden] { display: none; }\n\n.music-toggle.is-muted::after {\n  content: \"\";\n  position: absolute;\n  width: 26px;\n  height: 2px;\n  background: var(--gold);\n  transform: rotate(-45deg);\n}\n\n/* ============================================================\n   Scroll reveal &amp; reduced motion\n   ============================================================ */\n.reveal {\n  opacity: 0;\n  transform: translateY(24px);\n  transition: opacity 380ms ease-out, transform 380ms ease-out;\n}\n\n.reveal.revealed {\n  opacity: 1;\n  transform: none;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  .reveal { opacity: 1; transform: none; transition: none; }\n  .scroll-cue { animation: none; }\n  .btn { transition: none; }\n  .cover { transition: none; }\n}\n\n/* ---------- Desktop: kolom tetap di tengah ---------- */\n@media (min-width: 768px) {\n  body::before { opacity: 0.12; }\n  .column { padding: 2.75rem 2rem; }\n  .section { padding: 2.25rem 0; }\n}\n</style>\n</head>\n<body class=\"cover-open\" data-tanggal=\"2028-02-06T08:00:00+07:00\">\n\n  <!-- ============ 1. Cover / layar pembuka ============ -->\n  <div class=\"cover\" id=\"cover\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"cover-title\">\n    <div class=\"cover__batik\" aria-hidden=\"true\"></div>\n    <div class=\"cover__inner\">\n      <p class=\"cover__eyebrow\">The Wedding Of</p>\n      <h1 class=\"cover__names\" id=\"cover-title\"><span id=\"cover-pria\">Surya</span> <span class=\"amp\">&amp;</span> <span id=\"cover-wanita\">Fransiska</span></h1>\n      <p class=\"cover__date\" id=\"cover-date\">Minggu, 6 Februari 2028</p>\n      <p class=\"cover__hint\">Kepada Bapak/Ibu/Saudara/i, kami memohon doa restu.</p>\n      <button type=\"button\" class=\"btn btn--gold\" id=\"open-btn\">Buka Undangan</button>\n    </div>\n  </div>\n\n  <header class=\"site-header\" id=\"atas\">\n    <p class=\"site-header__brand\"><span id=\"brand-pria\">S</span> <span aria-hidden=\"true\">&amp;</span><span class=\"sr-only\">dan</span> <span id=\"brand-wanita\">F</span></p>\n  </header>\n\n  <main>\n    <!-- ============ 2. Hero ============ -->\n    <section class=\"hero\" aria-labelledby=\"hero-title\">\n      <div class=\"column\">\n        <div class=\"hero__photo\" aria-hidden=\"true\">\n          <span class=\"hero__monogram\"><span id=\"monogram-pria\">S</span><span class=\"hero__heart\">&hearts;</span><span id=\"monogram-wanita\">F</span></span>\n        </div>\n        <h2 class=\"hero__names\" id=\"hero-title\">Surya Septa Pratama &amp; Fransiska Wijaya</h2>\n        <p class=\"hero__date\" id=\"hero-date\">Minggu, 6 Februari 2028</p>\n        <div class=\"divider\" aria-hidden=\"true\"></div>\n        <a class=\"scroll-cue\" href=\"#countdown\" aria-label=\"Gulir ke bagian hitung mundur\">\n          <span aria-hidden=\"true\">&#8595;</span> Gulir ke bawah\n        </a>\n      </div>\n    </section>\n\n    <!-- ============ 3. Countdown ============ -->\n    <section class=\"section\" id=\"countdown\" aria-labelledby=\"countdown-title\">\n      <div class=\"column reveal\">\n        <h3 class=\"section__title\" id=\"countdown-title\">Menuju Hari Bahagia</h3>\n        <p class=\"sr-only\" id=\"countdown-status\" aria-live=\"polite\"></p>\n        <div class=\"countdown\" aria-hidden=\"true\">\n          <div class=\"countdown__box\"><span class=\"countdown__num\" id=\"cd-hari\">00</span><span class=\"countdown__label\">Hari</span></div>\n          <div class=\"countdown__box\"><span class=\"countdown__num\" id=\"cd-jam\">00</span><span class=\"countdown__label\">Jam</span></div>\n          <div class=\"countdown__box\"><span class=\"countdown__num\" id=\"cd-menit\">00</span><span class=\"countdown__label\">Menit</span></div>\n          <div class=\"countdown__box\"><span class=\"countdown__num\" id=\"cd-detik\">00</span><span class=\"countdown__label\">Detik</span></div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ============ 4. Mempelai ============ -->\n    <section class=\"section section--tinted\" id=\"mempelai\" aria-labelledby=\"mempelai-title\">\n      <div class=\"column reveal\">\n        <h3 class=\"section__title\" id=\"mempelai-title\">Mempelai</h3>\n        <p class=\"lead\"><strong id=\"pembuka\">Bismillahirrahmanirrahim</strong></p>\n        <blockquote class=\"quote\">\n          <p id=\"quote-teks\">&ldquo;Dan di antara tanda-tanda kebesaran-Nya ialah Dia menciptakan pasangan-pasangan untukmu dari jenismu sendiri, agar kamu merasa tenteram kepadanya, dan Dia menjadikan di antaramu rasa kasih dan sayang.&rdquo;</p>\n          <cite id=\"quote-sumber\">QS. Ar-Rum: 21</cite>\n        </blockquote>\n\n        <article class=\"couple-card\">\n          <div class=\"couple-card__badge\" aria-hidden=\"true\" id=\"pria-badge\">S</div>\n          <h4 class=\"couple-card__name\" id=\"pria-nama\">Surya Septa Pratama</h4>\n          <p class=\"couple-card__role\">Mempelai Pria</p>\n          <p class=\"couple-card__parents\" id=\"pria-orangtua\">Putra dari Bapak Aja Sukarja &amp; Ibu Sugiyarti</p>\n        </article>\n\n        <article class=\"couple-card\">\n          <div class=\"couple-card__badge\" aria-hidden=\"true\" id=\"wanita-badge\">F</div>\n          <h4 class=\"couple-card__name\" id=\"wanita-nama\">Fransiska Wijaya</h4>\n          <p class=\"couple-card__role\">Mempelai Wanita</p>\n          <p class=\"couple-card__parents\" id=\"wanita-orangtua\">Putri dari Bapak Wahyu &amp; Ibu Tati Widiyawati</p>\n        </article>\n      </div>\n    </section>\n\n    <!-- ============ 5. Acara ============ -->\n    <section class=\"section\" id=\"acara\" aria-labelledby=\"acara-title\">\n      <div class=\"column reveal\">\n        <h3 class=\"section__title\" id=\"acara-title\">Rangkaian Acara</h3>\n\n        <article class=\"event-card\">\n          <h4 class=\"event-card__title\">Akad Nikah</h4>\n          <p class=\"event-card__row\"><span class=\"event-card__icon\" aria-hidden=\"true\">&#128197;</span> <span id=\"akad-tanggal\">Minggu, 6 Februari 2028</span></p>\n          <p class=\"event-card__row\"><span class=\"event-card__icon\" aria-hidden=\"true\">&#128337;</span> <span id=\"akad-jam\">08.00&ndash;10.00 WIB</span></p>\n          <p class=\"event-card__row\"><span class=\"event-card__icon\" aria-hidden=\"true\">&#128205;</span> <span id=\"akad-lokasi\">Kediaman Mempelai Wanita</span></p>\n          <a class=\"btn btn--outline\" id=\"akad-maps\" href=\"https://maps.app.goo.gl/YFyc4B4BgszYhBEk7\" target=\"_blank\" rel=\"noopener\">Lihat Lokasi</a>\n        </article>\n\n        <article class=\"event-card\">\n          <h4 class=\"event-card__title\">Resepsi</h4>\n          <p class=\"event-card__row\"><span class=\"event-card__icon\" aria-hidden=\"true\">&#128197;</span> <span id=\"resepsi-tanggal\">Minggu, 6 Februari 2028</span></p>\n          <p class=\"event-card__row\"><span class=\"event-card__icon\" aria-hidden=\"true\">&#128337;</span> <span id=\"resepsi-jam\">11.00&ndash;14.00 WIB</span></p>\n          <p class=\"event-card__row\"><span class=\"event-card__icon\" aria-hidden=\"true\">&#128205;</span> <span id=\"resepsi-lokasi\">Kediaman Mempelai Wanita</span></p>\n          <a class=\"btn btn--outline\" id=\"resepsi-maps\" href=\"https://maps.app.goo.gl/YFyc4B4BgszYhBEk7\" target=\"_blank\" rel=\"noopener\">Lihat Lokasi</a>\n        </article>\n      </div>\n    </section>\n\n    <!-- ============ 6. Galeri ============ -->\n    <section class=\"section section--tinted\" id=\"galeri\" aria-labelledby=\"galeri-title\">\n      <div class=\"column reveal\">\n        <h3 class=\"section__title\" id=\"galeri-title\">Galeri Kenangan</h3>\n        <div class=\"gallery\">\n          <img class=\"gallery__tile\" src=\"data:image/svg+xml;base64,\" alt=\"Monogram S dan F di dalam medali motif kawung bernuansa merah marun\" width=\"600\" height=\"600\" loading=\"lazy\" decoding=\"async\">\n          <img class=\"gallery__tile\" src=\"data:image/svg+xml;base64,\" alt=\"Bintang-bintang motif truntum dengan cincin emas di tengah di atas latar gading\" width=\"600\" height=\"600\" loading=\"lazy\" decoding=\"async\">\n          <img class=\"gallery__tile\" src=\"data:image/svg+xml;base64,\" alt=\"Lapisan awan mega mendung sebagai cakrawala dengan piringan emas di atas latar sogan\" width=\"600\" height=\"600\" loading=\"lazy\" decoding=\"async\">\n          <img class=\"gallery__tile\" src=\"data:image/svg+xml;base64,\" alt=\"Pita diagonal motif parang dengan segel wajik emas di atas latar marun\" width=\"600\" height=\"600\" loading=\"lazy\" decoding=\"async\">\n          <img class=\"gallery__tile\" src=\"data:image/svg+xml;base64,\" alt=\"Tanggal pernikahan 06 02 2028 dengan ornamen sudut motif sidomukti di atas latar gading\" width=\"600\" height=\"600\" loading=\"lazy\" decoding=\"async\">\n          <img class=\"gallery__tile\" src=\"data:image/svg+xml;base64,\" alt=\"Bingkai motif kawung penuh dengan quatrefoil emas kosong di tengah, pas untuk foto\" width=\"600\" height=\"600\" loading=\"lazy\" decoding=\"async\">\n        </div>\n      </div>\n    </section>\n\n    <!-- ============ 7. Ucapan &amp; RSVP ============ -->\n    <section class=\"section\" id=\"ucapan\" aria-labelledby=\"ucapan-title\">\n      <div class=\"column reveal\">\n        <h3 class=\"section__title\" id=\"ucapan-title\">Ucapan &amp; Kehadiran</h3>\n        <p class=\"lead\" id=\"rsvp-count\">0 ucapan diterima</p>\n\n        <form class=\"rsvp-form\" id=\"rsvp-form\" novalidate>\n          <div class=\"field\">\n            <label for=\"rsvp-nama\">Nama <span aria-hidden=\"true\">*</span></label>\n            <input type=\"text\" id=\"rsvp-nama\" name=\"nama\" required autocomplete=\"name\" placeholder=\"Nama Anda\">\n            <p class=\"field__error\" id=\"err-nama\" hidden>Mohon isi nama Anda.</p>\n          </div>\n\n          <fieldset class=\"field field--radio\">\n            <legend>Kehadiran <span aria-hidden=\"true\">*</span></legend>\n            <label class=\"radio\"><input type=\"radio\" name=\"kehadiran\" value=\"Hadir\" required> <span>Hadir</span></label>\n            <label class=\"radio\"><input type=\"radio\" name=\"kehadiran\" value=\"Tidak Hadir\"> <span>Tidak Hadir</span></label>\n            <label class=\"radio\"><input type=\"radio\" name=\"kehadiran\" value=\"Masih Ragu\"> <span>Masih Ragu</span></label>\n            <p class=\"field__error\" id=\"err-kehadiran\" hidden>Mohon pilih status kehadiran.</p>\n          </fieldset>\n\n          <div class=\"field\">\n            <label for=\"rsvp-pesan\">Ucapan &amp; Doa</label>\n            <textarea id=\"rsvp-pesan\" name=\"pesan\" rows=\"4\" placeholder=\"Tulis ucapan dan doa terbaikmu...\"></textarea>\n          </div>\n\n          <button type=\"submit\" class=\"btn btn--gold\">Kirim Ucapan</button>\n        </form>\n\n        <ul class=\"rsvp-list\" id=\"rsvp-list\" aria-live=\"polite\"></ul>\n      </div>\n    </section>\n\n    <!-- ============ 8. Amplop digital ============ -->\n    <section class=\"section section--tinted\" id=\"amplop\" aria-labelledby=\"amplop-title\">\n      <div class=\"column reveal\">\n        <h3 class=\"section__title\" id=\"amplop-title\">Amplop Digital</h3>\n        <p class=\"lead\">Doa restu Anda adalah hadiah terbaik. Namun jika ingin memberi tanda kasih, silakan melalui rekening berikut.</p>\n        <div class=\"bank-card\">\n          <p class=\"bank-card__bank\" id=\"bank-nama\">Bank BCA</p>\n          <p class=\"bank-card__number\" id=\"bank-number\">1234567890</p>\n          <p class=\"bank-card__name\" id=\"bank-atasnama\">a.n. Fransiska Wijaya</p>\n          <button type=\"button\" class=\"btn btn--outline\" id=\"copy-btn\">Salin Nomor</button>\n        </div>\n      </div>\n    </section>\n\n    <!-- ============ 9. Penutup ============ -->\n    <section class=\"closing\" aria-labelledby=\"closing-title\">\n      <div class=\"column reveal\">\n        <h3 class=\"section__title\" id=\"closing-title\">Terima Kasih</h3>\n        <p class=\"lead\">Merupakan suatu kebahagiaan bagi kami apabila Bapak/Ibu/Saudara/i berkenan hadir dan memberikan doa restu. Atas kehadiran serta doanya, kami ucapkan terima kasih.</p>\n        <p class=\"closing__names\">Kami yang berbahagia,<br><strong id=\"closing-names\">Surya &amp; Fransiska</strong></p>\n        <p class=\"closing__hashtag\" id=\"closing-hashtag\">#SuryaFransiska</p>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"site-footer\">\n    <p>Dibuat dengan penuh kasih &bull; <span id=\"footer-hashtag\">#SuryaFransiska</span></p>\n  </footer>\n\n  <audio id=\"bg-music\" src=\"__AUDIO_SRC__\" loop preload=\"auto\" aria-hidden=\"true\"></audio>\n  <button type=\"button\" class=\"music-toggle\" id=\"music-toggle\" aria-pressed=\"false\" aria-label=\"Putar musik\" hidden>\n    <span aria-hidden=\"true\">&#9834;</span>\n  </button>\n\n  <script>\n(function () {\n  'use strict';\n\n  var REDUCED = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  function $(id) { return document.getElementById(id); }\n\n  /* ---------- 0. Musik latar ---------- */\n  var music = $('bg-music');\n  var musicBtn = $('music-toggle');\n\n  function syncMusicBtn() {\n    if (!music || !musicBtn) return;\n    var playing = !music.paused;\n    musicBtn.classList.toggle('is-muted', !playing);\n    musicBtn.setAttribute('aria-pressed', playing ? 'true' : 'false');\n    musicBtn.setAttribute('aria-label', playing ? 'Jeda musik' : 'Putar musik');\n  }\n\n  if (music && musicBtn) {\n    musicBtn.addEventListener('click', function () {\n      if (music.paused) {\n        music.play().catch(function () { /* diblokir browser — biarkan tombol sebagai jalan manual */ });\n      } else {\n        music.pause();\n      }\n    });\n    music.addEventListener('play', syncMusicBtn);\n    music.addEventListener('pause', syncMusicBtn);\n    music.addEventListener('error', function () { musicBtn.hidden = true; });\n  }\n\n  /* ---------- 1. Cover / buka undangan ---------- */\n  var cover = $('cover');\n  var openBtn = $('open-btn');\n\n  // Konten di belakang cover tidak boleh dijangkau Tab selama cover terbuka\n  var behindCover = document.querySelectorAll('.site-header, main, .site-footer');\n  function setBehindInert(state) {\n    Array.prototype.forEach.call(behindCover, function (el) { el.inert = state; });\n  }\n\n  if (openBtn && cover) {\n    setBehindInert(true);\n    openBtn.addEventListener('click', function () {\n      cover.classList.add('is-open');\n      document.body.classList.remove('cover-open');\n      cover.setAttribute('aria-hidden', 'true');\n      setBehindInert(false);\n      if (music && musicBtn) {\n        musicBtn.hidden = false;\n        music.play().catch(function () { /* autoplay ditolak — tombol musik tetap bisa dipakai */ });\n      }\n      // Fokus ke konten utama agar navigasi keyboard lanjut dari sini\n      var heroTitle = document.getElementById('hero-title');\n      if (heroTitle) {\n        heroTitle.setAttribute('tabindex', '-1');\n        heroTitle.focus({ preventScroll: true });\n      }\n    });\n  }\n\n  /* ---------- 2. Countdown ---------- */\n  var TANGGAL = (document.body && document.body.getAttribute('data-tanggal')) || '2028-02-06T08:00:00+07:00';\n  var TARGET = new Date(TANGGAL).getTime();\n  var cd = {\n    hari: $('cd-hari'), jam: $('cd-jam'), menit: $('cd-menit'), detik: $('cd-detik')\n  };\n  var cdStatus = $('countdown-status');\n  var announced = false;\n\n  function pad(n) { return (n < 10 ? '0' : '') + n; }\n\n  function tick() {\n    var diff = Math.max(0, TARGET - Date.now());\n    var s = Math.floor(diff / 1000);\n    var d = Math.floor(s / 86400);\n    var h = Math.floor((s % 86400) / 3600);\n    var m = Math.floor((s % 3600) / 60);\n    var sec = s % 60;\n\n    if (cd.hari) cd.hari.textContent = pad(d);\n    if (cd.jam) cd.jam.textContent = pad(h);\n    if (cd.menit) cd.menit.textContent = pad(m);\n    if (cd.detik) cd.detik.textContent = pad(sec);\n\n    if (cdStatus && !announced) {\n      announced = true;\n      cdStatus.textContent = diff === 0\n        ? 'Hari bahagia telah tiba.'\n        : 'Menuju hari bahagia: ' + d + ' hari lagi.';\n    }\n    return diff;\n  }\n\n  if (cd.hari || cd.jam || cd.menit || cd.detik) {\n    tick();\n    window.setInterval(tick, 1000);\n  }\n\n  /* ---------- 3. Scroll reveal ---------- */\n  var revealEls = Array.prototype.slice.call(document.querySelectorAll('.reveal'));\n  if ('IntersectionObserver' in window && !REDUCED) {\n    var io = new IntersectionObserver(function (entries) {\n      entries.forEach(function (entry) {\n        if (entry.isIntersecting) {\n          entry.target.classList.add('revealed');\n          io.unobserve(entry.target);\n        }\n      });\n    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });\n    revealEls.forEach(function (el) { io.observe(el); });\n  } else {\n    revealEls.forEach(function (el) { el.classList.add('revealed'); });\n  }\n\n  /* ---------- 4. Ucapan & RSVP (localStorage) ---------- */\n  var STORAGE_KEY = 'rsvp-ucapan';\n  var form = $('rsvp-form');\n  var listEl = $('rsvp-list');\n  var countEl = $('rsvp-count');\n  var errNama = $('err-nama');\n  var errKehadiran = $('err-kehadiran');\n\n  function loadEntries() {\n    try {\n      var raw = window.localStorage.getItem(STORAGE_KEY);\n      var parsed = raw ? JSON.parse(raw) : [];\n      return Array.isArray(parsed) ? parsed : [];\n    } catch (e) {\n      return [];\n    }\n  }\n\n  function saveEntries(entries) {\n    try {\n      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(entries));\n    } catch (e) {\n      /* localStorage bisa gagal (mode privat/penuh) — daftar tetap tampil di sesi ini */\n    }\n  }\n\n  function badgeClass(value) {\n    return 'rsvp-item__badge badge--' + value.toLowerCase().replace(/\\s+/g, '-');\n  }\n\n  function entryToItem(entry) {\n    var li = document.createElement('li');\n    li.className = 'rsvp-item';\n\n    var head = document.createElement('div');\n    head.className = 'rsvp-item__head';\n\n    var name = document.createElement('span');\n    name.className = 'rsvp-item__name';\n    name.textContent = entry.nama;\n\n    var badge = document.createElement('span');\n    badge.className = badgeClass(entry.kehadiran);\n    badge.textContent = entry.kehadiran;\n\n    head.appendChild(name);\n    head.appendChild(badge);\n    li.appendChild(head);\n\n    if (entry.pesan) {\n      var msg = document.createElement('p');\n      msg.className = 'rsvp-item__msg';\n      msg.textContent = entry.pesan;\n      li.appendChild(msg);\n    }\n\n    var time = document.createElement('time');\n    time.className = 'rsvp-item__time';\n    time.setAttribute('datetime', entry.waktuIso);\n    time.textContent = entry.waktuTeks;\n    li.appendChild(time);\n\n    return li;\n  }\n\n  function render() {\n    if (!listEl || !countEl) return;\n    var entries = loadEntries();\n    listEl.textContent = '';\n    entries.forEach(function (entry) {\n      listEl.appendChild(entryToItem(entry));\n    });\n    countEl.textContent = entries.length + ' ucapan diterima';\n  }\n\n  function formatTime(iso) {\n    try {\n      return new Date(iso).toLocaleString('id-ID', {\n        day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit'\n      });\n    } catch (e) {\n      return '';\n    }\n  }\n\n  if (form) {\n    form.addEventListener('submit', function (ev) {\n      ev.preventDefault();\n\n      var namaInput = $('rsvp-nama');\n      var pesanInput = $('rsvp-pesan');\n      var kehadiranInput = form.querySelector('input[name=\"kehadiran\"]:checked');\n\n      var nama = namaInput ? namaInput.value.trim() : '';\n      var pesan = pesanInput ? pesanInput.value.trim() : '';\n      var kehadiran = kehadiranInput ? kehadiranInput.value : '';\n\n      var valid = true;\n      if (errNama) errNama.hidden = true;\n      if (errKehadiran) errKehadiran.hidden = true;\n\n      if (!nama) {\n        if (errNama) errNama.hidden = false;\n        valid = false;\n      }\n      if (!kehadiran) {\n        if (errKehadiran) errKehadiran.hidden = false;\n        valid = false;\n      }\n      if (!valid) return;\n\n      var now = new Date().toISOString();\n      var entries = loadEntries();\n      entries.unshift({\n        nama: nama,\n        kehadiran: kehadiran,\n        pesan: pesan,\n        waktuIso: now,\n        waktuTeks: formatTime(now)\n      });\n      saveEntries(entries);\n      render();\n\n      form.reset();\n      if (pesanInput) pesanInput.focus();\n    });\n  }\n\n  render();\n\n  /* ---------- 5. Salin nomor rekening ---------- */\n  var copyBtn = $('copy-btn');\n  var bankEl = $('bank-number');\n  var BANK_NUMBER = bankEl ? bankEl.textContent.trim() : '';\n  var copyTimer = null;\n\n  function showCopied() {\n    if (!copyBtn) return;\n    copyBtn.textContent = 'Tersalin \\u2713';\n    if (copyTimer) window.clearTimeout(copyTimer);\n    copyTimer = window.setTimeout(function () {\n      if (copyBtn) copyBtn.textContent = 'Salin Nomor';\n    }, 2000);\n  }\n\n  function copyFallback(text) {\n    var ta = document.createElement('textarea');\n    ta.value = text;\n    ta.setAttribute('readonly', '');\n    ta.style.position = 'fixed';\n    ta.style.opacity = '0';\n    document.body.appendChild(ta);\n    ta.select();\n    try {\n      document.execCommand('copy');\n      showCopied();\n    } catch (e) {\n      if (copyBtn) copyBtn.textContent = 'Gagal menyalin';\n    }\n    document.body.removeChild(ta);\n  }\n\n  if (copyBtn) {\n    copyBtn.addEventListener('click', function () {\n      if (!BANK_NUMBER) return;\n      if (navigator.clipboard && navigator.clipboard.writeText) {\n        navigator.clipboard.writeText(BANK_NUMBER).then(showCopied, function () {\n          copyFallback(BANK_NUMBER);\n        });\n      } else {\n        copyFallback(BANK_NUMBER);\n      }\n    });\n  }\n})();\n</script>\n</body>\n</html>\n", audioPlaceholder: "__AUDIO_SRC__" };
